import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Security","description":"","frontmatter":{},"headers":[],"relativePath":"guide/security.md","filePath":"guide/security.md","lastUpdated":1787092618000}`),a={name:`guide/security.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to “Security”">​</a></h1><p>The <a href="https://github.com/ni-c/rustpad-mcp/blob/main/SECURITY.md" target="_blank" rel="noreferrer">SECURITY.md</a> in the repository is the authoritative policy (and the place to report vulnerabilities — privately, please). This page explains the model.</p><h2 id="start-from-what-rustpad-is" tabindex="-1">Start from what Rustpad is <a class="header-anchor" href="#start-from-what-rustpad-is" aria-label="Permalink to “Start from what Rustpad is”">​</a></h2><p><strong>Rustpad has no authentication.</strong> Anyone who can reach the instance and knows or guesses a pad id can read and rewrite that pad. rustpad-mcp adds no access control on top, because there is none to enforce. Consequences:</p><ul><li>Point the server only at an instance whose pads you consider public within their network.</li><li>Never store secrets in pads.</li><li>Treat every pad as attacker-controlled text — including text this server wrote earlier, which may have been edited since.</li></ul><h2 id="untrusted-content-marking" tabindex="-1">Untrusted content marking <a class="header-anchor" href="#untrusted-content-marking" aria-label="Permalink to “Untrusted content marking”">​</a></h2><p>Every tool result that can contain pad-derived text is prefixed with an explicit marker telling the model it is data to report on, never instructions to follow. That covers <code>get_document</code>, <code>get_document_info</code> (user names and the editor language are chosen by arbitrary clients) and even surviving upstream error bodies. Confirmation prompts quote pad ids and character counts only.</p><h2 id="confirmation-tokens" tabindex="-1">Confirmation tokens <a class="header-anchor" href="#confirmation-tokens" aria-label="Permalink to “Confirmation tokens”">​</a></h2><p><code>set_document</code> on a non-empty pad is the destructive operation here — the old content is unrecoverable. It requires a server-generated, single-use token that only ever appears in a <em>previous</em> tool result and is bound to the pad id <strong>and</strong> a fingerprint of the replacement text. A confirmation obtained for one replacement cannot execute a different one.</p><h2 id="the-server-is-untrusted-too" tabindex="-1">The server is untrusted too <a class="header-anchor" href="#the-server-is-untrusted-too" aria-label="Permalink to “The server is untrusted too”">​</a></h2><p><code>RUSTPAD_URL</code> decides what sits at the other end of the WebSocket, so the session layer treats the upstream itself as hostile input: every wait has a wall-clock deadline, the message queue, frame size, tracked-user count and inbound document size are capped, History messages are structurally validated, and a connection that fails mid-handshake is closed, not leaked.</p><h2 id="tls" tabindex="-1">TLS <a class="header-anchor" href="#tls" aria-label="Permalink to “TLS”">​</a></h2><p><code>RUSTPAD_INSECURE_TLS=true</code> disables certificate validation <strong>only</strong> for the configured connection, via a scoped dispatcher — never process-wide, and <code>NODE_TLS_REJECT_UNAUTHORIZED</code> is never touched.</p><h2 id="read-only-mode" tabindex="-1">Read-only mode <a class="header-anchor" href="#read-only-mode" aria-label="Permalink to “Read-only mode”">​</a></h2><p><code>RUSTPAD_READ_ONLY=true</code> does not &quot;block&quot; the write tools — it does not register them, so the connection never advertises capabilities it would refuse.</p>`,15)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};